          </Alert>
          <div className="flex gap-10" style={{ marginTop: 12 }}>
            <button className="btn btn-danger" onClick={() => remove(confirmDel)}>Delete Permanently</button>
            <button className="btn btn-ghost" onClick={() => setConfirmDel(null)}>Cancel</button>
